import csv, json
from decimal import Decimal
from pathlib import Path


def build(source, destination):
    rows = list(csv.DictReader(Path(source).open(newline="")))
    posted = {}  # id -> amount of first posted occurrence
    pending_ids = set()
    counts = {}
    for r in rows:
        rid, status = r["id"], r["status"]
        counts[rid] = counts.get(rid, 0) + 1
        if status == "posted":
            posted.setdefault(rid, Decimal(r["amount"]))
        elif status == "pending":
            pending_ids.add(rid)

    included_ids = sorted(posted)
    total = sum(posted.values(), Decimal("0"))
    total_str = f"{total:.2f}"
    report = {"total": total_str, "rows": len(included_ids)}
    reconciliation = {
        "included_ids": included_ids,
        "excluded_pending_ids": sorted(pending_ids),
        "duplicate_ids": sorted(i for i, c in counts.items() if c > 1),
        "total": total_str,
    }
    dest = Path(destination)
    dest.write_text(json.dumps(report))
    dest.with_name("reconciliation.json").write_text(json.dumps(reconciliation))


if __name__ == "__main__":
    build("transactions.csv", "report.json")

